UPDATE servers SET details_json = json_set(details_json, '$.tools', json('[{"name":"read_text_file","description":"Read complete contents of a file as text"},{"name":"read_media_file","description":"Read a file and return it as a base64-encoded content block with its MIME type"},{"name":"read_multiple_files","description":"Read multiple files simultaneously"},{"name":"write_file","description":"Create new file or overwrite existing (exercise caution with this)"},{"name":"append_file","description":"Append text to the end of a file, creating the file if it does not exist"},{"name":"edit_file","description":"Make selective edits using advanced pattern matching and formatting"},{"name":"create_directory","description":"Create new directory or ensure it exists"},{"name":"list_directory","description":"List the entries directly inside a directory, one per line, with [FILE] or [DIR] prefixes"},{"name":"list_directory_with_sizes","description":"List the entries directly inside a directory with [FILE] or [DIR] prefixes, including file sizes"},{"name":"move_file","description":"Move or rename files and directories"},{"name":"copy_file","description":"Copy a file to a new location, without its content passing through the"},{"name":"search_files","description":"Recursively find files/directories by name (a glob over their paths), not"},{"name":"directory_tree","description":"Get recursive JSON tree structure of directory contents"},{"name":"get_file_info","description":"Get detailed file/directory metadata"},{"name":"list_allowed_directories","description":"List all directories the server is allowed to access"}]'), '$.toolsCoverage', 'upstream-documented-inventory; runtime-not-tested', '$.contentSource', 'https://github.com/modelcontextprotocol/servers/blob/main/src/filesystem/README.md', '$.contentReviewedAt', '2026-11-23', '$.contentVerification', 'upstream-source-reviewed; runtime-not-tested', '$.lifecycle', 'maintained', '$.prerequisites', json('["Node.js and npm/npx.","At