UPDATE servers SET details_json = json_set(details_json, '$.tools', json('[{"name":"create_entities","description":"Create multiple new entities in the knowledge graph"},{"name":"create_relations","description":"Create multiple new relations between entities"},{"name":"add_observations","description":"Add new observations to existing entities"},{"name":"delete_entities","description":"Remove whole entities, with all their observations"},{"name":"delete_observations","description":"Remove specific observations from entities"},{"name":"delete_relations","description":"Remove specific relations from the graph, keeping the entities they connect (to remove an entity itself, use `delete_entities`)"},{"name":"read_graph","description":"Read the entire knowledge graph"},{"name":"search_nodes","description":"Search for nodes based on query"},{"name":"open_nodes","description":"Retrieve specific nodes by name"}]'), '$.toolsCoverage', 'upstream-documented-inventory; runtime-not-tested', '$.contentSource', 'https://github.com/modelcontextprotocol/servers/blob/main/src/memory/README.md', '$.contentReviewedAt', '2026-11-23', '$.contentVerification', 'upstream-source-reviewed; runtime-not-tested', '$.lifecycle', 'maintained', '$.prerequisites', json('["Node.js 24 or later for npx/source execution.","A writable location for the persistent knowledge-graph file.","Protect memory contents if they include sensitive data."]')) WHERE id = 'memory-mcp';

UPDATE servers SET details_json = json_set(details_json, '$.tools', json('[{"name":"browser_click","description":"Perform click on a web page"},{"name":"browser_close","description":"Close the browser and all open tabs."},{"name":"browser_console_messages","description":"Returns all console messages"},{"name":"browser_drag","description":"Perform drag and drop between two elements"},{"name":"browser_drop","description":"Drop files or MIME-typed data onto an element, as if dragged from outside the page. At least one of \"paths\" or \"data\" must be provided."},{"name":"browser_emulate_media","description":"Emulate CSS media features for the page, for example switch between the light and dark color scheme. Omitted parameters are left unchanged; null clears an override."},{"name":"browser_evaluate","description":"Evaluate JavaScript expression on page or element"},{"name":"browser_file_upload","description":"Upload one or multiple files"},{"name":"browser_fill_form","description":"Fill multiple form fields"},{"name":"browser_find","description":"Search the accessibility snapshot of the current page for text or a regular expression. Returns matching snapshot nodes with a few lines of surrounding context (like search snippets), each shown under its path from the root of the tree, which is cheaper than capturing the whole snapshot when you only need to locate an element and its ref."},{"name":"browser_handle_dialog","description":"Handle a dialog"},{"name":"browser_hover","description":"Hover over element on page"},{"name":"browser_navigate","description":"Navigate to a URL"},{"name":"browser_navigate_back","description":"Go back to the previous page in the history"},{"name":"browser_network_request","description":"Returns full details (headers and body) of a single network request, or a single part if `part` is set. Use the number from browser_network_requests."},{"name":"browser_network_requests","description":"Returns a numbered list of network requests since loading the page. Use browser_network_request with the number to get full details."},{"name":"browser_press_key","description":"Press a key on the keyboard"},{"name":"browser_resize","description":"Resize the browser window"},{"name":"browser_run_code_unsafe","description":"Run a Playwright code snippet. Unsafe: executes arbitrary JavaScript in the Playwright server process and is RCE-equivalent."},{"name":"browser_select_option","description":"Select an option in a dropdown"},{"name":"browser_snapshot","description":"Capture accessibility snapshot of the current page, this is better than screenshot"},{"name":"browser_take_screenshot","description":"Take a screenshot of the current page. Use browser_snapshot for actions by default. With the vision capability enabled, use screenshot coordinates with the coordinate-based mouse tools for elements not exposed in the accessibility snapshot."},{"name":"browser_type","description":"Type text into editable element"},{"name":"browser_wait_for","description":"Wait for text to appear or disappear or a specified time to pass. When both text and textGone are provided, waits for the first one to happen"},{"name":"browser_tabs","description":"List, create, close, or select a browser tab."},{"name":"browser_get_config","description":"Get the final resolved config after merging CLI options, environment variables and config file."},{"name":"browser_network_state_set","description":"Sets the browser network state to online or offline. When offline, all network requests will fail."},{"name":"browser_route","description":"Set up a route to mock network requests matching a URL pattern"},{"name":"browser_route_list","description":"List all active network routes"},{"name":"browser_unroute","description":"Remove network routes matching a pattern (or all routes if no pattern specified)"},{"name":"browser_cookie_clear","description":"Clear all cookies"},{"name":"browser_cookie_delete","description":"Delete a specific cookie (optionally only on a given domain/path)"},{"name":"browser_cookie_get","description":"Get a specific cookie by name"},{"name":"browser_cookie_list","description":"List all cookies (optionally filtered by domain/path)"},{"name":"browser_cookie_set","description":"Set a cookie with optional flags (domain, path, expires, httpOnly, secure, sameSite)"},{"name":"browser_localstorage_clear","description":"Clear all localStorage"},{"name":"browser_localstorage_delete","description":"Delete a localStorage item"},{"name":"browser_localstorage_get","description":"Get a localStorage item by key"},{"name":"browser_localstorage_list","description":"List all localStorage key-value pairs"},{"name":"browser_localstorage_set","description":"Set a localStorage item"},{"name":"browser_sessionstorage_clear","description":"Clear all sessionStorage"},{"name":"browser_sessionstorage_delete","description":"Delete a sessionStorage item"},{"name":"browser_sessionstorage_get","description":"Get a sessionStorage item by key"},{"name":"browser_sessionstorage_list","description":"List all sessionStorage key-value pairs"},{"name":"browser_sessionstorage_set","description":"Set a sessionStorage item"},{"name":"browser_set_storage_state","description":"Restore storage state (cookies, local storage) from a file. This clears existing cookies and local storage before restoring."},{"name":"browser_storage_state","description":"Save storage state (cookies, local storage) to a file for later reuse"},{"name":"browser_annotate","description":"Open the Playwright Dashboard in annotation mode for the current page and wait for the user to draw annotations. Returns the annotated screenshot, ARIA snapshot, and the list of annotations."},{"name":"browser_hide_highlight","description":"Remove a highlight overlay previously added for the element."},{"name":"browser_highlight","description":"Show a persistent highlight overlay around the element on the page."},{"name":"browser_resume","description":"Resume script execution after it was paused. When called with step set to true, execution will pause again before the next action."},{"name":"browser_start_recording","description":"Start recording actions that the user performs in the browser as Playwright code. Use it when the user wants to demonstrate a flow manually. Call browser_stop_recording when the user says they are done to retrieve the recorded actions."},{"name":"browser_start_tracing","description":"Start trace recording"},{"name":"browser_start_video","description":"Start video recording"},{"name":"browser_stop_recording","description":"Stop the recording started with browser_start_recording and return the recorded actions as Playwright code."},{"name":"browser_stop_tracing","description":"Stop trace recording"},{"name":"browser_stop_video","description":"Stop video recording"},{"name":"browser_video_chapter","description":"Add a chapter marker to the video recording. Shows a full-screen chapter card with blurred backdrop."},{"name":"browser_video_hide_actions","description":"Stop annotating actions performed on the page."},{"name":"browser_video_show_actions","description":"Annotate subsequent actions performed on the page with a callout that names the action and, when styled, marks the action point and highlights the target element. Useful while video recording or screencasting."},{"name":"browser_mouse_click_xy","description":"Click mouse button at a given position"},{"name":"browser_mouse_down","description":"Press mouse down"},{"name":"browser_mouse_drag_xy","description":"Drag left mouse button to a given position"},{"name":"browser_mouse_move_xy","description":"Move mouse to a given position"},{"name":"browser_mouse_up","description":"Press mouse up"},{"name":"browser_mouse_wheel","description":"Scroll mouse wheel"},{"name":"browser_pdf_save","description":"Save page as PDF"},{"name":"browser_generate_locator","description":"Generate locator for the given element to use in tests"},{"name":"browser_verify_element_visible","description":"Verify element is visible on the page"},{"name":"browser_verify_list_visible","description":"Verify list is visible on the page"},{"name":"browser_verify_text_visible","description":"Verify text is visible on the page. Prefer browser_verify_element_visible if possible."},{"name":"browser_verify_value","description":"Verify element value"}]'), '$.toolsCoverage', 'upstream-generated-all-profiles; optional capability groups depend on configuration', '$.contentSource', 'https://github.com/microsoft/playwright-mcp/blob/main/README.md', '$.contentReviewedAt', '2026-11-23', '$.contentVerification', 'upstream-source-reviewed; runtime-not-tested', '$.lifecycle', 'maintained', '$.prerequisites', json('["Node.js LTS and npm/npx.","A compatible MCP client and installed/supported browser runtime.","Only automate websites and accounts you are authorized to access."]')) WHERE id = 'playwright-mcp';

