"description":"List label values matching a selector for a label name"},{"name":"list_pyroscope_profile_types","description":"List available profile types"},{"name":"query_pyroscope","description":"Query profiles, metrics, or both from Pyroscope"},{"name":"get_assertions","description":"Get assertion summary for a given entity"},{"name":"agento11y_manage_conversations","description":"List, search, and fetch LLM conversations from Grafana Agent Observability"},{"name":"agento11y_manage_generations","description":"Fetch LLM generation details and evaluation scores from Grafana Agent Observability"},{"name":"agento11y_manage_agents","description":"Read the agent catalog: list agents, get one agent version in full, list version history, and per-version score aggregates"},{"name":"agento11y_manage_evaluators","description":"Manage evaluators, evaluator templates, and the judge catalog (list, get, upsert, fork, test, delete)"},{"name":"agento11y_manage_eval_rules","description":"Manage eval rules and guards (list, get, create, update, preview, delete)"},{"name":"agento11y_manage_eval_collections","description":"Manage saved conversations and the collections that group them (list, get, save, create, update, delete, add and remove members)"},{"name":"agento11y_manage_experiments","description":"Read offline experiments, their trials, scores, artifact metadata, and filter facets; update and cancel an experiment"},{"name":"agento11y_manage_test_suites","description":"Manage the test suites that offline experiments run against, their versions, and their test cases (list, get, create, update, draft, publish, upsert, delete)"},{"name":"ask_assistant","description":"Send a prompt to Grafana Assistant and return the full text reply (multi-turn via `contextId`)"},{"name":"generate_deeplink","description":"Generate accurate deeplink URLs for Grafana resources"},{"name":"get_annotations","description":"Fetch annotations with filters"},{"name":"create_annotation","description":"Create a new annotation (standard or Graphite format)"},{"name":"update_annotation","description":"Update specific fields of an annotation (partial update)"},{"name":"delete_annotation","description":"Delete an annotation by ID"},{"name":"get_annotation_tags","description":"List annotation tags with optional filtering"},{"name":"list_snapshots","description":"List dashboard snapshots with optional query and limit filters"},{"name":"get_snapshot","description":"Get snapshot metadata and dashboard payload by snapshot key"},{"name":"create_snapshot","description":"Create a dashboard snapshot from a full dashboard payload"},{"name":"delete_snapshot","description":"Delete a dashboard snapshot by snapshot key"},{"name":"get_panel_image","description":"Render a stored dashboard or panel, a provisioning preview, or an ad-hoc Explore view as a PNG image"},{"name":"list_provisioning_repositories","description":"List provisioning repositories (e.g. git-sync sources) with their source URL, branch, sync state, and health"},{"name":"validate_provisioning_file","description":"Dry-run-apply a file from a provisioning repository and report admission validation errors"},{"name":"search_docs","description":"Search Grafana documentation or list product groups (omit query to list products)"},{"name":"get_doc","description":"Fetch a documentation page; set outline_only for headings, or section for bounded retrieval"},{"name":"search_tempo_traces","description":"Search traces with TraceQL"},{"name":"query_tempo_metrics","description":"Compute metrics from traces with TraceQL"},{"name":"get_tempo_trace","description":"Fetch a trace by ID"},{"name":"diff_tempo_traces","description":"Compare two traces"},{"name":"list_tempo_attribute_names","description":"List span and resource attribute names"},{"name":"list_tempo_attribute_values","description":"List values for a trace attribute"},{"name":"get_tempo_traceql_docs","description":"Get TraceQL documentation"},{"name":"query_graphite","description":"Query Graphite metrics"},{"name":"query_graphite_density","description":"Query Graphite metric density"},{"name":"list_graphite_metrics","description":"List Graphite metrics"},{"name":"list_graphite_tags","description":"List Graphite tags"},{"name":"get_plugin","description":"Get an installed plugin"},{"name":"search_plugin_information","description":"Search the grafana.com plugin catalog"},{"name":"install_plugin","description":"Install a plugin"},{"name":"grafana_api_request","description":"Call a Grafana HTTP API endpoint"}]'), '$.toolsCoverage', 'upstream-README-all-categories; availability depends on Grafana plugins, feature flags and permissions', '$.contentSource', 'https://github.com/grafana/mcp-grafana/blob/main/README.md', '$.contentReviewedAt', '2026-11-23', '$.contentVerification', 'upstream-source-reviewed; runtime-not-tested', '$.lifecycle', 'maintained', '$.prerequisites', json('["Grafana 9.0 or later and a reachable Grafana URL.","Python uv/uvx for the documented example.","A Grafana service-account token with appropriate permissions; some tools require plugins or Grafana Cloud features."]')) WHERE id = 'grafana-mcp';

UPDATE servers SET name = 'AWS Bedrock Knowledge Bases MCP', author = 'awslabs', github_url = 'https://github.com/awslabs/mcp/tree/main/src/bedrock-kb-retrieval-mcp-server', description = 'AWS Labs MCP server for Amazon Bedrock Knowledge Bases: list accessible knowledge bases, retrieve content and use managed knowledge-base agentic retrieval.', details_json = json_set(details_json, '$.tools', json('[{"name":"ListKnowledgeBases","description":"List accessible Amazon Bedrock knowledge bases."},{"name":"QueryKnowledgeBases","description":"Retrieve relevant content from Bedrock knowledge bases."},{"name":"AgenticQueryKnowledgeBases","description":"Perform agentic retrieval and cited response generation for supported managed knowledge bases."}]'), '$.toolsCoverage', 'upstream-documented-inventory; runtime-not-tested', '$.contentSource', 'https://github.com/awslabs/mcp/blob/main/src/bedrock-kb-retrieval-mcp-server/awslabs/bedrock_kb_retrieval_mcp_server/server.py', '$.contentReviewedAt', '2026-11-23', '$.contentVerification', 'upstream-source-reviewed; runtime-not-tested', '$.summary', 'AWS Labs maintained Amazon Bedrock Knowledge Bases retrieval MCP server, including list, query and managed-KB agentic retrieval.', '$.lifecycle', 'maintained', '$.installations', json('[{"client":"Claude Desktop","title":"AWS Labs UVX","config":{"mcpServers":{"aws-kb-retrieval":{"command":"uvx","args":["awslabs.bedrock-kb-retrieval-mcp-server@latest"],"env":{"AWS_PROFILE":"your-profile-name","AWS_REGION":"us-east-1"}}}},"notes":"Use AWS profile with least-privilege Bedrock permissions. Agentic retrieval requires a supported managed knowledge base. Not runtime-tested."}]'), '$.prerequisites', json('["Python uv/uvx installed.","AWS credentials via a configured profile and selected region.","An accessible Amazon Bedrock Knowledge Base and appropriate IAM permissions."]'), '$.security', json('["Use least-privilege IAM permissions and short-lived AWS credentials where possible.","Retrieval may expose sensitive knowledge-base contents to the configured MCP client.","Agentic retrieval may invoke a foundation model and incur additional charges."]')) WHERE id = 'aws-kb-mcp';

UPDATE servers SET name = 'Postgres MCP Pro', author = 'crystaldba', github_url = 'https://github.com/crystaldba/postgres-mcp', description = 'Maintained PostgreSQL MCP server with schema inspection, restricted SQL queries, execution plans, indexing recommendations and database health diagnostics.', details_json = json_set(details_json, '$.tools', json('[{"name":"list_schemas","description":"Lists all database schemas available in the PostgreSQL instance."},{"name":"list_objects","description":"Lists database objects (tables, views, sequences, extensions) within a specified schema."},{"name":"get_object_details","description":"Provides information about a specific database object, for example, a table''s columns, constraints, and indexes."},{"name":"execute_sql","description":"Executes SQL statements on the database, with read-only limitations when connected in restricted mode."},{"name":"explain_query","description":"Gets the execution plan for a SQL query describing how PostgreSQL will process it and exposing the query planner''s cost model. Can be invoked with hypothetical indexes to simulate the behavior after adding indexes."},{"name":"get_top_queries","description":"Reports the slowest SQL queries based on total execution time using `pg_stat_statements` data."},{"name":"analyze_workload_indexes","description":"Analyzes the database workload to identify resource-intensive queries, then recommends optimal indexes for them."},{"name":"analyze_query_indexes","description":"Analyzes a list of specific SQL queries (up to 10) and recommends optimal indexes for them."},{"name":"analyze_db_health","description":"Performs comprehensive health checks including: buffer cache hit rates, connection health, constraint validation, index health (duplicate/unused/invalid), sequence limits, and vacuum health."}]'), '$.toolsCoverage', 'upstream-documented-inventory; runtime-not-tested', '$.contentSource', 'https://github.com/crystaldba/postgres-mcp/blob/main/README.md', '$.contentReviewedAt', '2026-11-23', '$.contentVerification', 'upstream-source-reviewed; runtime-not-tested', '$.summary', 'Postgres MCP Pro by CrystalDBA supports PostgreSQL schema inspection, SQL queries, execution plans, index analysis and health checks.', '$.lifecycle', 'maintained', '$.installations', json('[{"client":"Claude Desktop","title":"Postgres MCP Pro (restricted)","config":{"mcpServers":{"postgres":{"command":"uvx","args":["postgres-mcp","--access-mode=restricted"],"env":{"DATABASE_URI":"postgresql://username:password@localhost:5432/dbname"}}}},"notes":"Restricted mode enforces read-only transactions; use a database role with read-only permissions. Not runtime-tested."}]'), '$.prerequisites', json('["Python uv/uvx installed.","A reachable PostgreSQL database and connection URI.","A dedicated least-privilege read-only PostgreSQL account."]'), '$.security', json('["Use --access-mode=restricted for production; unrestricted mode permits writes.","Protect DATABASE_URI credentials and restrict network access.","Some diagnostics require PostgreSQL extensions or additional read privileges."]')) WHERE id = 'postgres-mcp';

