UPDATE servers SET details_json = json_set(details_json, '$.toolsCoverage', 'archived-reference-inventory; migration-pending', '$.contentVerification', 'archived-reference; replacement not yet verified end-to-end') WHERE id = 'puppeteer-mcp';

UPDATE servers SET details_json = json_set(details_json, '$.toolsCoverage', 'archived-reference-inventory; migration-pending', '$.contentVerification', 'archived-reference; replacement not yet verified end-to-end') WHERE id = 'sqlite-mcp';

UPDATE servers SET details_json = json_set(details_json, '$.toolsCoverage', 'archived-reference-inventory; migration-pending', '$.contentVerification', 'archived-reference; replacement not yet verified end-to-end') WHERE id = 'sentry-mcp';

SELECT id, json_extract(details_json, '$.lifecycle') AS lifecycle, json_array_length(json_extract(details_json, '$.tools')) AS tool_count FROM servers ORDER BY id;
